const description: { en: string; ja: string } = {"en":"Join sixteen broad alternating arcs into a continuous vine. Place a scroll with a round tip at each turn, alternating outside and inside the vine.","ja":"内外に曲がる太い円弧を十六本つなぎ、一本の蔓を作ります。曲がり目ごとに先の丸い巻きを、蔓の外と内へ交互に付けます。"};

export default construction;
